/**
 * Shared command plumbing: connection loading, error mapping,
 * confirmation flow, activity logging, formatting.
 */
import { Markup } from "telegraf";
import { getOrCreateUser, getConnection, logActivity, } from "../store.js";
import { ProviderError } from "../providers/http.js";
import { providerDef } from "../providers/index.js";
import { checkLimit } from "../ratelimit.js";
import { randomHex } from "../vault.js";
export function escapeHtml(s) {
    return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}
/** Anything that looks like a provider/bot token must never be echoed. */
export function looksSecret(text) {
    return /(ghp_|gho_|ghu_|ghs_|github_pat_|sk-[A-Za-z0-9]|glpat-|xox[baprs]-|AKIA[0-9A-Z]{16}|Bearer\s+[A-Za-z0-9]|^\s*\d+:[A-Za-z0-9_-]{30,})/.test(text);
}
export async function userFromCtx(ctx) {
    const from = ctx.from;
    if (!from)
        return null;
    return getOrCreateUser({
        telegramUserId: from.id,
        telegramUsername: from.username,
        firstName: from.first_name,
        languageCode: from.language_code,
    });
}
/**
 * Run a provider operation with connection + rate limit + error mapping
 * + activity logging. Replies with a connect prompt when not connected.
 * `fn` may return a plain HTML string or { text, extra } for buttons.
 */
export async function withProvider(ctx, provider, action, fn) {
    const user = await userFromCtx(ctx);
    if (!user)
        return void (await ctx.reply("I couldn't identify your Telegram account."));
    const limit = checkLimit(user.telegramUserId, "providerCalls");
    if (!limit.ok) {
        return void (await ctx.reply(`⏳ Provider calls are rate limited — try again in ${limit.retryAfterSec}s.`));
    }
    const conn = await getConnection(user.telegramUserId, provider);
    if (!conn) {
        const def = providerDef(provider);
        const { connectOptions, storageProvider } = await import("../oauth.js");
        const canLogin = connectOptions().some((o) => storageProvider(o.provider) === provider);
        return void (await ctx.reply(`${def?.icon ?? "🔌"} <b>${def?.displayName ?? provider} isn't connected yet.</b>\n\n` +
            (canLogin
                ? `Use /connect ${provider} — log in in one tap, nothing to copy (or paste a token if you prefer).`
                : `Use /connect ${provider} and paste a token — one-tap Log in buttons appear there once the OAuth apps are configured.`), { parse_mode: "HTML" }));
    }
    try {
        const result = await fn({ authType: conn.authType, token: conn.token, identity: conn.identity }, user);
        await logActivity(user.telegramUserId, provider, action).catch(() => { });
        if (typeof result === "string") {
            await ctx.reply(result, { parse_mode: "HTML", link_preview_options: { is_disabled: true } });
        }
        else if (result && typeof result.text === "string") {
            await ctx.reply(result.text, {
                parse_mode: "HTML",
                link_preview_options: { is_disabled: true },
                ...(result.extra ?? {}),
            });
        }
    }
    catch (err) {
        await ctx.reply(formatError(err), { parse_mode: "HTML" });
    }
}
export function formatError(err) {
    if (err instanceof ProviderError) {
        return `❌ ${escapeHtml(err.message)}${err.hint ? `\n\n💡 ${escapeHtml(err.hint)}` : ""}`;
    }
    return `❌ ${escapeHtml(String(err?.message ?? err))}`;
}
const confirmRegistry = new Map();
export function askConfirm(ctx, key, question, yesLabel, run) {
    // Unique per confirmation and per user — two users confirming similar
    // actions can never trigger each other's closures.
    const scopedKey = `${ctx.from?.id ?? 0}:${randomHex(6)}:${key}`.slice(0, 56);
    confirmRegistry.set(scopedKey, run);
    // Auto-expire keys so the map can't grow forever.
    setTimeout(() => confirmRegistry.delete(scopedKey), 10 * 60 * 1000).unref?.();
    return ctx.reply(`⚠️ ${question}`, {
        parse_mode: "HTML",
        reply_markup: Markup.inlineKeyboard([
            [Markup.button.callback(yesLabel, `confirm:${scopedKey}`)],
            [Markup.button.callback("🚫 Cancel", "flow:cancel")],
        ]).reply_markup,
    });
}
export async function runConfirm(key) {
    const fn = confirmRegistry.get(key);
    if (!fn)
        return false;
    confirmRegistry.delete(key);
    await fn();
    return true;
}
// ── Coming-soon placeholder ────────────────────────────────────────
export function comingSoon(ctx, feature) {
    return ctx.reply(`⏳ <b>${escapeHtml(feature)} support is coming soon to Tandem.</b>\n\n` +
        `We're perfecting <b>GitHub</b> and <b>Vercel</b> first — ${escapeHtml(feature)} is on the roadmap and lands in one of the next updates.\n\n` +
        `Meanwhile /repos, /deploy, /search and friends all work today.`, { parse_mode: "HTML" });
}
// ── Formatting helpers ──────────────────────────────────────────────
export function fmtAgo(isoOrMs) {
    if (!isoOrMs)
        return "";
    const t = typeof isoOrMs === "number" ? isoOrMs : new Date(isoOrMs).getTime();
    const diff = Date.now() - t;
    if (diff < 60_000)
        return "just now";
    if (diff < 3600_000)
        return `${Math.floor(diff / 60_000)}m ago`;
    if (diff < 86400_000)
        return `${Math.floor(diff / 3600_000)}h ago`;
    return `${Math.floor(diff / 86400_000)}d ago`;
}
export function chunk(rows, per) {
    const out = [];
    for (let i = 0; i < rows.length; i += per)
        out.push(rows.slice(i, i + per));
    return out;
}
